    // V120: complete signed16 range expressed as parallel bit-prefix tests.
    // The positive +2048 endpoint is intentional and remains inclusive.
    function automatic logic raw_range_valid(input logic [15:0] coefficient);
        raw_range_valid=(coefficient[15:11]==5'd0) ||
            (coefficient[15:11]==5'd31) || (coefficient==16'h0800);
    endfunction
`ifndef SYNTHESIS
    always_ff @(posedge clk)if(!cancelled && state==RAW && raw_valid)begin
        assert(raw_range_valid(raw_coefficient)==
            (raw_coefficient>=-2048 && raw_coefficient<=2048))
            else $fatal(1,"V120 full signed16 raw range predicate mismatch");
    end
`endif

